class UserPreferenceProvider(ContextProvider):
    def __init__(self):
        super().__init__('user-preferences')

    async def before_run(self, *, agent, session, context, state):
        if fav := state.get('favorite_food'):
            context.extend_instructions(self.source_id, f'Favourite food: {fav}.')

    async def after_run(self, *, agent, session, context, state):
        for m in context.input_messages:
            if 'favorite food is' in (m.text or '').lower():
                state['favorite_food'] = m.text.lower().split('favorite food is', 1)[1].strip(' .')

